[HarnessEntry(id='continual_arc_task_6b14fc71_rule', kind='memory', title='Continual-ARC task-6b14fc71 rule', content='For task-6b14fc71, the input is a grid of framed 5×5 symbol tiles arranged in tile rows. In each tile row, identify the unique odd-pattern tile. Stack the selected complete tiles vertically in original tile-row order, preserving the frame color and separators; do not output only the bare tile interiors. For three tile rows, the result is 19×7 (three 5×5 interiors plus framing and separators), not 15×5. This output format was confirmed by a correct submission.', path='continual_arc/task-6b14fc71', scope='global', reference={}, arguments={}, metadata={'scope': 'global'}, source='refine', created_at='2026-09-28T16:31:05.083175+00:00', updated_at='2026-09-28T16:38:44.112Z', version=2), HarnessEntry(id='continual_arc_task_a4019f09_rule', kind='memory', title='Continual-ARC task-a4019f09 single-edge-marker rule', content="For Continual-ARC task-a4019f09 when there is exactly one color-2 marker on an edge, the marker defines a row or column cut line. Keep color-7 cells on that line in place. From the marker toward the grid interior, recolor background cells along the line to 2 through the farthest encountered 7; preserve those 7 cells and leave cells beyond the farthest 7 unchanged. Move all 7 cells strictly on each side of the line as rigid patterns into the corresponding two corners on the marker's side, aligning each region's bounding box to its destination corner and clearing its original cells. Preserve the background elsewhere. This rule was validated for left- and right-edge markers and by a correct test submission. Do not infer behavior for multiple markers from this rule.", path='continual_arc/task-a4019f09', scope='global', reference={}, arguments={}, metadata={'scope': 'global'}, source='refine', created_at='2026-09-28T20:45:04.022Z', updated_at='2026-09-28T20:45:04.022Z', version=1), HarnessEntry(id='continual_arc_task_9f5e21c1_rule', kind='memory', title='Continual-ARC task-9f5e21c1 rule', content="For Continual-ARC task-9f5e21c1, large square panels are base-color templates with background-colored holes, and smaller patterned objects also contain background-colored holes. Count 4-connected components of background holes in each panel and object, then pair panels and objects with equal counts. Center each object in its paired panel. Construct a panel-sized output tile using the panel's base color throughout, then preserve the object's non-background-colored cells at the centered position; object's background holes are filled with the panel base color. Ignore the panel's own hole pixels when composing the tile; they are used only for matching. Arrange the composite tiles in the panels' original row-major layout.", path='general', scope='global', reference={}, arguments={}, metadata={'scope': 'global'}, source='refine', created_at='2026-09-28T19:13:02.191Z', updated_at='2026-09-28T19:17:15.754Z', version=2), HarnessEntry(id='continual_arc_task_cc2878ca_rule', kind='memory', title='Continual-ARC task-cc2878ca framed-tile movement rule', content='For Continual-ARC task-cc2878ca, the grid contains complete 5×5 framed tiles, each with a 3×3 center. Preserve every tile’s rows, frame, center, and the background. Tiles framed in color 8 slide horizontally left; tiles framed in color 2 slide horizontally right. When vertical spans overlap, a tile is blocked only by another tile in the same frame-color/movement class. Opposite-color tiles do not block one another and may pass or cross despite overlapping vertical spans. Demo evidence and a correctly solved test validate this rule. A broader assumption that any tile blocks movement caused two incorrect submissions.', path='general', scope='global', reference={}, arguments={}, metadata={'scope': 'global', 'evidence': 'Validated by demonstrations and successful test submission'}, source='refine', created_at='2026-09-28T19:20:51.673Z', updated_at='2026-09-28T19:44:17.268Z', version=2)]
